// ============================================================================
// Reader Reading Palettes
// ============================================================================
enum class ReadingTheme {
    Day,
    Night,
    Sepia,
    DarkSepia
};

struct ReaderPalette {
    QColor bg;
    QColor text;
    QColor surface;
    QColor border;
    QColor gutter;
};

inline ReaderPalette getReaderPalette(ReadingTheme theme) {
    switch (theme) {
    case ReadingTheme::Day:
        return {
            QColor{"#ffffff"},
            QColor{"#1a1d20"},
            QColor{"#f5f7fa"},
            QColor{"#dbe0e8"},
            QColor{"#e6ebf2"}
        };
    case ReadingTheme::Night:
        return {
            QColor{"#181a1f"},
            QColor{"#e2e4e8"},
            QColor{"#22252b"},
            QColor{"#323742"},
            QColor{"#2a2e38"}
        };
    case ReadingTheme::Sepia:
        return {
            QColor{"#faf3e0"},
            QColor{"#3d2e1e"},
            QColor{"#f2e7cd"},
            QColor{"#e3d5b5"},
            QColor{"#ebe0c2"}
        };
    case ReadingTheme::DarkSepia:
        return {
            QColor{"#2b241e"},
            QColor{"#ddd1be"},
            QColor{"#383029"},
            QColor{"#4d433b"},
            QColor{"#423931"}
        };
    }
    return getReaderPalette(ReadingTheme::Day);
}

