// ============================================================================
// Typography Fonts
// ============================================================================
inline QFont getUiFont(int pointSize = 10, int weight = QFont::Normal) {
    QFont font("Segoe UI");
    font.setPointSize(pointSize);
    font.setWeight(static_cast<QFont::Weight>(weight));
    font.setStyleHint(QFont::SansSerif);
    return font;
}

inline QFont getBookFont(int pointSize = 12, const QString& family = "Georgia") {
    QFont font(family);
    font.setPointSize(pointSize);
    font.setStyleHint(QFont::Serif);
    return font;
}

